import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.C0KMm31j.js";const o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_02_six_concepts_overview.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_02_state_observation_belief.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_02_action_execution_chain.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_02_merging_example.png",c="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_02_modeling_checklist.png",f=JSON.parse('{"title":"别再把状态和观测混为一谈：拆开强化学习的六个核心概念","description":"强化学习代码里最常见的变量，往往只有 obs、action、reward 和几个结束标志。它们看起来像一组简单的接口参数，却决定了智能体究竟看见什么、能够控制什么、环境如何响应，以及训练最终会偏向什么行为。概念一旦混淆，算法即使收敛，也可能只是在认真解决一个被定义错的问题。","frontmatter":{"title":"别再把状态和观测混为一谈：拆开强化学习的六个核心概念","description":"强化学习代码里最常见的变量，往往只有 obs、action、reward 和几个结束标志。它们看起来像一组简单的接口参数，却决定了智能体究竟看见什么、能够控制什么、环境如何响应，以及训练最终会偏向什么行为。概念一旦混淆，算法即使收敛，也可能只是在认真解决一个被定义错的问题。","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":16,"source":"2026-08-13/rl_series_02_agent_environment_state_action_reward.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_02_six_concepts_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-02-agent-environment-state-action-reward"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"别再把状态和观测混为一谈：拆开强化学习的六个核心概念"}],["meta",{"property":"og:description","content":"强化学习代码里最常见的变量，往往只有 obs、action、reward 和几个结束标志。它们看起来像一组简单的接口参数，却决定了智能体究竟看见什么、能够控制什么、环境如何响应，以及训练最终会偏向什么行为。概念一旦混淆，算法即使收敛，也可能只是在认真解决一个被定义错的问题。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-02-agent-environment-state-action-reward"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_02_six_concepts_overview.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"别再把状态和观测混为一谈：拆开强化学习的六个核心概念"}],["meta",{"name":"twitter:description","content":"强化学习代码里最常见的变量，往往只有 obs、action、reward 和几个结束标志。它们看起来像一组简单的接口参数，却决定了智能体究竟看见什么、能够控制什么、环境如何响应，以及训练最终会偏向什么行为。概念一旦混淆，算法即使收敛，也可能只是在认真解决一个被定义错的问题。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_02_six_concepts_overview.png"}]],"prev":{"text":"强化学习到底在解决什么问题？先别急着训练智能体","link":"/rl/rl-series-01-what-problem-does-rl-solve"},"next":{"text":"马尔可夫不是“失忆”：一篇看懂强化学习的数学骨架","link":"/rl/rl-series-03-markov-decision-process"}},"headers":[],"relativePath":"rl/rl-series-02-agent-environment-state-action-reward.md","filePath":"rl/rl-series-02-agent-environment-state-action-reward.md","lastUpdated":null}'),h={name:"rl/rl-series-02-agent-environment-state-action-reward.md"};function p(d,a,_,u,b,m){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="别再把状态和观测混为一谈-拆开强化学习的六个核心概念" tabindex="-1">别再把状态和观测混为一谈：拆开强化学习的六个核心概念 <a class="header-anchor" href="#别再把状态和观测混为一谈-拆开强化学习的六个核心概念" aria-label="Permalink to &quot;别再把状态和观测混为一谈：拆开强化学习的六个核心概念&quot;">​</a></h1><p>强化学习代码里最常见的变量，往往只有 <code>obs</code>、<code>action</code>、<code>reward</code> 和几个结束标志。它们看起来像一组简单的接口参数，却决定了智能体究竟看见什么、能够控制什么、环境如何响应，以及训练最终会偏向什么行为。概念一旦混淆，算法即使收敛，也可能只是在认真解决一个被定义错的问题。</p><p><img src="'+o+`" alt="六个核心概念总览"></p><h2 id="一、结论先说" tabindex="-1">一、结论先说 <a class="header-anchor" href="#一、结论先说" aria-label="Permalink to &quot;一、结论先说&quot;">​</a></h2><p>强化学习（Reinforcement Learning，强化学习）的最小闭环可以用六个概念描述：智能体（Agent，智能体）做决策，环境（Environment，环境）承载智能体以外的变化；环境内部具有状态（State，状态），智能体只能获得观测（Observation，观测）；智能体输出动作（Action，动作），环境再返回奖励（Reward，奖励）和新的观测。</p><p>这六个词不是可以随意替换的同义词。状态不一定能被智能体直接看到，观测不一定足以还原真实世界，动作命令不一定等于执行器的实际响应，单步奖励也不等于一段轨迹的最终价值。</p><p>对自动驾驶而言，最值得记住的是：传感器给出的只是观测，车辆和交通环境仍有大量隐藏状态；策略输出的也许只是期望转角，真实转角还会经过限幅、速率限制、延迟和底盘动态。把这些差异抹掉，往往比选错算法造成的影响更大。</p><h2 id="二、先看完整交互闭环" tabindex="-1">二、先看完整交互闭环 <a class="header-anchor" href="#二、先看完整交互闭环" aria-label="Permalink to &quot;二、先看完整交互闭环&quot;">​</a></h2><h3 id="_2-1-一个时间步发生了什么" tabindex="-1">2.1 一个时间步发生了什么 <a class="header-anchor" href="#_2-1-一个时间步发生了什么" aria-label="Permalink to &quot;2.1 一个时间步发生了什么&quot;">​</a></h3><p>在时刻 $t$，智能体收到观测 $o_t$，根据策略选择动作 $a_t$。环境执行或处理这个动作，内部状态由 $s_t$ 转移到 $s_{t+1}$，随后产生奖励 $r_{t+1}$ 和下一观测 $o_{t+1}$。</p><p>可以把这个过程写成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>观测 o_t → 智能体 → 动作 a_t → 环境</span></span>
<span class="line"><span>   ↑                            ↓</span></span>
<span class="line"><span>奖励 r_t ← 新观测 o_t ← 状态转移</span></span></code></pre></div><p>这里故意同时保留了 $s$ 和 $o$。如果环境完全可观测，它们可能包含等价的信息；如果环境部分可观测，智能体只能通过当前观测与历史信息估计真实状态。</p><h3 id="_2-2-轨迹是学习真正使用的数据" tabindex="-1">2.2 轨迹是学习真正使用的数据 <a class="header-anchor" href="#_2-2-轨迹是学习真正使用的数据" aria-label="Permalink to &quot;2.2 轨迹是学习真正使用的数据&quot;">​</a></h3><p>交互不断重复后，会得到轨迹（Trajectory，轨迹）：</p><p>$$ \\tau=(o_0,a_0,r_1,o_1,a_1,r_2,\\ldots) $$</p><p>强化学习处理的不是互不相关的单点样本，而是具有时间关联的轨迹。动作会影响后续状态，后续状态又决定智能体还能看到什么、选择什么。因此，数据不是预先固定的，而是由策略与环境共同生成的。</p><h2 id="三、智能体不是某个神经网络" tabindex="-1">三、智能体不是某个神经网络 <a class="header-anchor" href="#三、智能体不是某个神经网络" aria-label="Permalink to &quot;三、智能体不是某个神经网络&quot;">​</a></h2><h3 id="_3-1-智能体的职责是作出决策" tabindex="-1">3.1 智能体的职责是作出决策 <a class="header-anchor" href="#_3-1-智能体的职责是作出决策" aria-label="Permalink to &quot;3.1 智能体的职责是作出决策&quot;">​</a></h3><p>智能体是决策主体。它接收可用信息，按照策略（Policy，策略）输出动作，并通过交互数据更新自己的决策方式。</p><p>智能体内部可以包含策略网络、价值函数、环境模型、历史编码器、探索机制和学习算法，也可以完全没有神经网络。一个查表的 Q-learning（Q 学习）程序、一个基于规则的探索器，甚至一个尚未学习的随机策略，都可以扮演智能体。</p><p>所以，“智能体”描述的是系统角色，不是某种模型结构。策略网络只是这个角色可能使用的一个部件。</p><h3 id="_3-2-智能体边界需要人为定义" tabindex="-1">3.2 智能体边界需要人为定义 <a class="header-anchor" href="#_3-2-智能体边界需要人为定义" aria-label="Permalink to &quot;3.2 智能体边界需要人为定义&quot;">​</a></h3><p>在自动驾驶任务里，智能体可以只负责行为决策，动作是“保持车道、向左变道、向右变道”；也可以负责轨迹规划，动作是一条未来轨迹；还可以直接输出加速度和转角。</p><p>边界选得越靠近执行器，策略越需要处理车辆动力学、延迟和安全约束；边界选得越靠近高层决策，环境就必须包含规划器和控制器对高层指令的响应。没有天然正确的边界，但边界必须写清楚。</p><h3 id="_3-3-策略与学习算法不要混为一谈" tabindex="-1">3.3 策略与学习算法不要混为一谈 <a class="header-anchor" href="#_3-3-策略与学习算法不要混为一谈" aria-label="Permalink to &quot;3.3 策略与学习算法不要混为一谈&quot;">​</a></h3><p>策略是从信息到动作的映射，可以写成确定性形式 $a=\\pi(o)$，也可以写成随机性形式 $a\\sim\\pi(\\cdot|o)$。学习算法负责调整策略或价值函数的参数。</p><p>训练结束后，部署系统通常只保留策略推理所需的部分，而不会在车上继续执行完整训练流程。说“PPO（近端策略优化）在控制车辆”并不严谨，更准确的说法是：使用 PPO 训练得到的策略在根据观测输出动作。</p><h2 id="四、环境不是一张地图" tabindex="-1">四、环境不是一张地图 <a class="header-anchor" href="#四、环境不是一张地图" aria-label="Permalink to &quot;四、环境不是一张地图&quot;">​</a></h2><h3 id="_4-1-环境包含智能体之外的一切" tabindex="-1">4.1 环境包含智能体之外的一切 <a class="header-anchor" href="#_4-1-环境包含智能体之外的一切" aria-label="Permalink to &quot;4.1 环境包含智能体之外的一切&quot;">​</a></h3><p>环境接收动作，推进世界，产生下一状态、观测、奖励和结束信号。地图只是环境的一部分，车辆动力学、道路结构、交通参与者、传感器模型、执行器约束、随机扰动与仿真时钟都可能属于环境。</p><p>在车道保持 toy（玩具）环境中，环境可能只有横向误差、航向误差、道路曲率和简单车辆模型；在高保真仿真中，环境还会包含轮胎、底盘、传感器噪声、遮挡、路面附着和其他车辆行为。二者都可以用于强化学习，但它们支持的结论范围完全不同。</p><h3 id="_4-2-环境边界决定实验回答什么问题" tabindex="-1">4.2 环境边界决定实验回答什么问题 <a class="header-anchor" href="#_4-2-环境边界决定实验回答什么问题" aria-label="Permalink to &quot;4.2 环境边界决定实验回答什么问题&quot;">​</a></h3><p>如果环境直接把期望转角当作真实转角，实验回答的是理想执行条件下的决策问题；如果加入转角限幅、变化率和控制延迟，实验才开始覆盖执行器约束；如果还加入感知噪声和遮挡，才涉及不完全观测下的鲁棒性。</p><p>环境越简单，越容易定位算法机制，也越不能直接推断真实部署表现。最小环境的价值是验证因果链，不是模拟全部现实。</p><h3 id="_4-3-环境还负责结束条件" tabindex="-1">4.3 环境还负责结束条件 <a class="header-anchor" href="#_4-3-环境还负责结束条件" aria-label="Permalink to &quot;4.3 环境还负责结束条件&quot;">​</a></h3><p>现代 Gymnasium（强化学习环境接口）把回合结束分为 <code>terminated</code>（任务终止）与 <code>truncated</code>（外部截断）。到达目标、碰撞或违反任务定义，通常属于终止；达到最大步数或被外部时间限制停止，通常属于截断。</p><p>二者在界面上都让当前回合结束，但对价值估计的含义不同。任务真正结束后，通常不存在该回合的后续价值；被时间限制截断时，世界本来仍可以继续。把它们压成一个含义模糊的 <code>done</code>，可能让训练目标出现偏差。</p><h2 id="五、状态与观测是最容易混淆的一对" tabindex="-1">五、状态与观测是最容易混淆的一对 <a class="header-anchor" href="#五、状态与观测是最容易混淆的一对" aria-label="Permalink to &quot;五、状态与观测是最容易混淆的一对&quot;">​</a></h2><h3 id="_5-1-状态描述环境真正处于什么情况" tabindex="-1">5.1 状态描述环境真正处于什么情况 <a class="header-anchor" href="#_5-1-状态描述环境真正处于什么情况" aria-label="Permalink to &quot;5.1 状态描述环境真正处于什么情况&quot;">​</a></h3><p>状态应包含足以描述环境后续演化的信息。理想的马尔可夫状态（Markov State，马尔可夫状态）满足：在给定当前状态与动作后，预测下一状态不再需要更早的历史。</p><p>车辆的真实位置、速度、横摆角速度，周围车辆的意图与动态，路面附着系数，执行器内部状态，都可能属于环境状态。它们不一定全部可测，但依然会影响未来。</p><h3 id="_5-2-观测是智能体实际拿到的信息" tabindex="-1">5.2 观测是智能体实际拿到的信息 <a class="header-anchor" href="#_5-2-观测是智能体实际拿到的信息" aria-label="Permalink to &quot;5.2 观测是智能体实际拿到的信息&quot;">​</a></h3><p>观测来自传感器、通信和上游模块。摄像头图像、点云、目标列表、自车定位、规划参考线和历史控制量都可以是观测。它可能带有噪声、延迟、缺失或错误关联。</p><p><img src="`+n+'" alt="状态、观测与内部表征"></p><p>状态像真实世界的完整账本，观测像智能体在当前时刻拿到的一页摘要。摘要可能足够，也可能遗漏关键变量。自动驾驶中的遮挡就是典型例子：路口另一侧是否有行人属于真实状态，相机暂时看不到并不代表行人不存在。</p><h3 id="_5-3-完全可观测只是建模近似" tabindex="-1">5.3 完全可观测只是建模近似 <a class="header-anchor" href="#_5-3-完全可观测只是建模近似" aria-label="Permalink to &quot;5.3 完全可观测只是建模近似&quot;">​</a></h3><p>当观测足以代表环境状态时，可以把任务建模为马尔可夫决策过程（Markov Decision Process，马尔可夫决策过程）。当观测不能完整描述状态时，更接近部分可观测马尔可夫决策过程（Partially Observable Markov Decision Process，部分可观测马尔可夫决策过程）。</p><p>工程中常通过堆叠历史帧、加入速度与执行器状态、使用循环网络或维护 belief state（信念状态）来缓解信息缺失。但增加输入维度不等于自动恢复真实状态，关键是历史信息是否真的能推断隐藏变量。</p><h3 id="_5-4-泄露真值会制造虚假能力" tabindex="-1">5.4 泄露真值会制造虚假能力 <a class="header-anchor" href="#_5-4-泄露真值会制造虚假能力" aria-label="Permalink to &quot;5.4 泄露真值会制造虚假能力&quot;">​</a></h3><p>仿真器经常能直接访问所有物体的精确位置、速度和类别。如果训练时把这些真值交给策略，部署时却只能使用有噪声的感知结果，就产生了观测不一致。</p><p>这种策略可能在仿真评估中表现很好，却依赖现实中拿不到的信息。定义观测空间时，应逐项标记数据来源、更新频率、延迟、噪声和部署可用性。</p><h2 id="六、动作不一定等于真实执行结果" tabindex="-1">六、动作不一定等于真实执行结果 <a class="header-anchor" href="#六、动作不一定等于真实执行结果" aria-label="Permalink to &quot;六、动作不一定等于真实执行结果&quot;">​</a></h2><h3 id="_6-1-动作空间决定智能体能够改变什么" tabindex="-1">6.1 动作空间决定智能体能够改变什么 <a class="header-anchor" href="#_6-1-动作空间决定智能体能够改变什么" aria-label="Permalink to &quot;6.1 动作空间决定智能体能够改变什么&quot;">​</a></h3><p>动作空间（Action Space，动作空间）规定合法动作的集合。离散动作空间可以表示有限个行为选项，例如保持、变道或减速；连续动作空间可以表示实数控制量，例如期望加速度和前轮转角。</p><p>动作定义不能只考虑算法是否方便。把连续转角粗暴离散成左、中、右，虽然可以使用表格方法，却可能损失平滑控制所需的分辨率；让策略直接输出任意轨迹点，又可能让动作空间过大且难以满足运动学约束。</p><h3 id="_6-2-策略动作与执行动作之间还有链路" tabindex="-1">6.2 策略动作与执行动作之间还有链路 <a class="header-anchor" href="#_6-2-策略动作与执行动作之间还有链路" aria-label="Permalink to &quot;6.2 策略动作与执行动作之间还有链路&quot;">​</a></h3><p>在真实系统中，策略输出通常先经过安全过滤、限幅、变化率限制、控制分配和执行器动态，才形成实际施加到车辆的动作。</p><p><img src="'+s+'" alt="策略动作到真实执行"></p><p>因此需要区分：</p><ul><li>策略建议动作，例如期望转角。</li><li>安全层修正后的动作，例如投影到安全集合内的转角。</li><li>执行器接收的命令，例如经过限幅和速率限制的目标量。</li><li>车辆实际响应，例如受延迟和动力学影响后的真实转角。</li></ul><p>如果训练环境直接使用策略建议动作推进状态，而真实车辆存在完整执行链路，就会形成训练—部署差异。对规控任务而言，动作延迟和执行器状态往往应该进入环境状态或观测历史。</p><h3 id="_6-3-动作约束不是奖励惩罚的替代品" tabindex="-1">6.3 动作约束不是奖励惩罚的替代品 <a class="header-anchor" href="#_6-3-动作约束不是奖励惩罚的替代品" aria-label="Permalink to &quot;6.3 动作约束不是奖励惩罚的替代品&quot;">​</a></h3><p>明确禁止的动作应通过动作空间、投影、安全过滤或控制约束处理。仅在奖励里惩罚超限，意味着策略仍可以在收益足够大时选择违规动作。</p><p>奖励适合表达偏好，硬约束负责排除不可接受行为。两者承担的工程职责不同。</p><h2 id="七、奖励只是一个时刻的反馈" tabindex="-1">七、奖励只是一个时刻的反馈 <a class="header-anchor" href="#七、奖励只是一个时刻的反馈" aria-label="Permalink to &quot;七、奖励只是一个时刻的反馈&quot;">​</a></h2><h3 id="_7-1-奖励不是正确动作标签" tabindex="-1">7.1 奖励不是正确动作标签 <a class="header-anchor" href="#_7-1-奖励不是正确动作标签" aria-label="Permalink to &quot;7.1 奖励不是正确动作标签&quot;">​</a></h3><p>奖励是环境返回的标量反馈，用来表达某次状态转移对任务目标的贡献。它可以依赖当前状态、动作和下一状态，但通常不会告诉智能体应该改成哪个动作。</p><p>例如，车辆保持合理进度可以获得正奖励，急加速产生舒适性惩罚，碰撞产生较大负奖励。即使得到负奖励，智能体也只知道结果不理想，并没有获得唯一的正确控制指令。</p><h3 id="_7-2-奖励与回报不能混用" tabindex="-1">7.2 奖励与回报不能混用 <a class="header-anchor" href="#_7-2-奖励与回报不能混用" aria-label="Permalink to &quot;7.2 奖励与回报不能混用&quot;">​</a></h3><p>奖励 $r_{t+1}$ 是一次环境转移产生的即时信号，回报（Return，回报）$G_t$ 是从当前时刻开始的一串折扣奖励：</p><p>$$ G_t=r_{t+1}+\\gamma r_{t+2}+\\gamma^2r_{t+3}+\\cdots $$</p><p>折扣因子（Discount Factor，折扣因子）$\\gamma$ 控制未来奖励在当前评价中的权重。强化学习通常希望最大化期望回报，而不是贪心地最大化眼前奖励。</p><h3 id="_7-3-奖励设计必须接受反例检查" tabindex="-1">7.3 奖励设计必须接受反例检查 <a class="header-anchor" href="#_7-3-奖励设计必须接受反例检查" aria-label="Permalink to &quot;7.3 奖励设计必须接受反例检查&quot;">​</a></h3><p>奖励函数写完后，应主动寻找“高分但错误”的策略。只奖励速度，车辆可能忽略舒适和风险；只惩罚碰撞，车辆可能停着不走；只用平均横向误差，策略可能偶尔产生不可接受的越界尖峰。</p><p>对安全关键任务，还要单独定义 cost（代价）或 constraint（约束）指标，例如碰撞率、越线率、最大约束违反量和安全层介入率。高回报只能说明策略适应了当前奖励，不能自动证明系统安全。</p><h2 id="八、把六个概念放进自动驾驶案例" tabindex="-1">八、把六个概念放进自动驾驶案例 <a class="header-anchor" href="#八、把六个概念放进自动驾驶案例" aria-label="Permalink to &quot;八、把六个概念放进自动驾驶案例&quot;">​</a></h2><h3 id="_8-1-任务选择为高速公路合流" tabindex="-1">8.1 任务选择为高速公路合流 <a class="header-anchor" href="#_8-1-任务选择为高速公路合流" aria-label="Permalink to &quot;8.1 任务选择为高速公路合流&quot;">​</a></h3><p>假设目标是在匝道末端安全、高效地汇入主路。智能体负责合流行为与纵向控制，底层转向跟踪由经典控制器完成。</p><p><img src="'+l+'" alt="高速公路合流建模示例"></p><h3 id="_8-2-智能体与环境边界" tabindex="-1">8.2 智能体与环境边界 <a class="header-anchor" href="#_8-2-智能体与环境边界" aria-label="Permalink to &quot;8.2 智能体与环境边界&quot;">​</a></h3><p>智能体读取自车和邻车信息，决定目标加速度与是否请求合流。环境包含车辆动力学、主路交通、匝道几何、底层控制器、传感器模型和其他车辆反应。</p><p>如果其他车辆永远匀速且不响应自车，任务学到的只是静态间隙选择；如果其他车辆会礼让、加速封堵或存在行为不确定性，才形成更真实的交互决策。</p><h3 id="_8-3-状态与观测" tabindex="-1">8.3 状态与观测 <a class="header-anchor" href="#_8-3-状态与观测" aria-label="Permalink to &quot;8.3 状态与观测&quot;">​</a></h3><p>环境状态可能包含所有车辆的精确位置、速度、加速度、意图和道路附着。智能体观测只能包含感知与定位系统可提供的数据，例如相对距离、相对速度、车道拓扑、剩余匝道长度和带噪声的目标跟踪结果。</p><p>邻车意图通常是隐藏状态。智能体可以利用一段历史轨迹推断，但不能把仿真器内部的“礼让类型”标签直接当作部署观测，除非真实系统也能可靠提供这一信息。</p><h3 id="_8-4-动作与执行链路" tabindex="-1">8.4 动作与执行链路 <a class="header-anchor" href="#_8-4-动作与执行链路" aria-label="Permalink to &quot;8.4 动作与执行链路&quot;">​</a></h3><p>动作可以定义为期望纵向加速度与合流请求。环境需要模拟加速度限幅、加加速度约束、控制延迟以及底层轨迹跟踪误差。实际车辆响应应反馈到下一观测，而不是默认命令立即无误差生效。</p><h3 id="_8-5-奖励与安全指标" tabindex="-1">8.5 奖励与安全指标 <a class="header-anchor" href="#_8-5-奖励与安全指标" aria-label="Permalink to &quot;8.5 奖励与安全指标&quot;">​</a></h3><p>奖励可以表达通行进度、合流成功、舒适性和不必要等待；碰撞、道路边界和最小安全距离则应另外形成明确约束与评估指标。</p><p>一个可信结论至少需要同时回答：是否成功合流、用了多久、舒适性如何、是否违反约束、最坏风险多大、策略是否依赖安全层频繁接管。</p><h2 id="九、现代环境接口如何对应这些概念" tabindex="-1">九、现代环境接口如何对应这些概念 <a class="header-anchor" href="#九、现代环境接口如何对应这些概念" aria-label="Permalink to &quot;九、现代环境接口如何对应这些概念&quot;">​</a></h2><h3 id="_9-1-reset-建立回合起点" tabindex="-1">9.1 <code>reset</code> 建立回合起点 <a class="header-anchor" href="#_9-1-reset-建立回合起点" aria-label="Permalink to &quot;9.1 `reset` 建立回合起点&quot;">​</a></h3><p>Gymnasium 的 <code>reset</code> 返回初始 <code>observation</code>（观测）和 <code>info</code>（附加信息）。随机种子也应通过 <code>reset(seed=...)</code> 设置，以便复现实验。</p><p><code>info</code> 可以携带诊断数据，但不要因为它方便就把部署时不可用的真值混入策略输入。训练器用于记录的信息与策略真正消费的观测应明确分离。</p><h3 id="_9-2-step-推进一个时间步" tabindex="-1">9.2 <code>step</code> 推进一个时间步 <a class="header-anchor" href="#_9-2-step-推进一个时间步" aria-label="Permalink to &quot;9.2 `step` 推进一个时间步&quot;">​</a></h3><p>现代接口返回：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>observation, reward, terminated, truncated, info</span></span></code></pre></div><p><code>observation</code> 是动作执行后的新观测，<code>reward</code> 是该次转移的反馈，<code>terminated</code> 表示任务按照环境定义结束，<code>truncated</code> 表示因时间或外部边界而停止，<code>info</code> 用于携带评价和诊断信息。</p><h3 id="_9-3-接口一致不代表语义正确" tabindex="-1">9.3 接口一致不代表语义正确 <a class="header-anchor" href="#_9-3-接口一致不代表语义正确" aria-label="Permalink to &quot;9.3 接口一致不代表语义正确&quot;">​</a></h3><p>只要类型匹配，环境就能运行，但它仍可能有观测泄露、奖励漏洞、时间索引错误或结束条件混淆。<code>step</code> 能返回五个值，只证明软件接口通了，不证明强化学习问题被正确建模。</p><h2 id="十、常见建模错误" tabindex="-1">十、常见建模错误 <a class="header-anchor" href="#十、常见建模错误" aria-label="Permalink to &quot;十、常见建模错误&quot;">​</a></h2><h3 id="_10-1-把所有可访问真值都塞进观测" tabindex="-1">10.1 把所有可访问真值都塞进观测 <a class="header-anchor" href="#_10-1-把所有可访问真值都塞进观测" aria-label="Permalink to &quot;10.1 把所有可访问真值都塞进观测&quot;">​</a></h3><p>这会让训练策略依赖部署系统拿不到的信息。正确做法是区分环境内部状态、训练诊断信息与在线策略观测。</p><h3 id="_10-2-忽略观测时间戳和延迟" tabindex="-1">10.2 忽略观测时间戳和延迟 <a class="header-anchor" href="#_10-2-忽略观测时间戳和延迟" aria-label="Permalink to &quot;10.2 忽略观测时间戳和延迟&quot;">​</a></h3><p>来自不同传感器或模块的数据可能并不同步。把旧的目标速度与新的自车位姿拼成一个向量，表面维度正确，实际却不是同一时刻的世界描述。</p><h3 id="_10-3-把动作命令当成真实响应" tabindex="-1">10.3 把动作命令当成真实响应 <a class="header-anchor" href="#_10-3-把动作命令当成真实响应" aria-label="Permalink to &quot;10.3 把动作命令当成真实响应&quot;">​</a></h3><p>执行器限幅、变化率、延迟和故障会改变动作效果。训练中省略这些环节，策略可能学会现实系统无法执行的高频控制。</p><h3 id="_10-4-用奖励包办所有安全要求" tabindex="-1">10.4 用奖励包办所有安全要求 <a class="header-anchor" href="#_10-4-用奖励包办所有安全要求" aria-label="Permalink to &quot;10.4 用奖励包办所有安全要求&quot;">​</a></h3><p>有限惩罚无法表达绝对不可接受。碰撞、越界和稳定性边界需要独立约束、评价和失效保护。</p><h3 id="_10-5-混淆终止与截断" tabindex="-1">10.5 混淆终止与截断 <a class="header-anchor" href="#_10-5-混淆终止与截断" aria-label="Permalink to &quot;10.5 混淆终止与截断&quot;">​</a></h3><p>任务失败、任务成功与达到最大步数具有不同语义。混在一个结束标志里，会影响成功率统计，也可能影响价值函数的 bootstrap（自举）目标。</p><h2 id="十一、建模前的最小检查表" tabindex="-1">十一、建模前的最小检查表 <a class="header-anchor" href="#十一、建模前的最小检查表" aria-label="Permalink to &quot;十一、建模前的最小检查表&quot;">​</a></h2><p><img src="'+c+'" alt="强化学习建模检查表"></p><ul><li>智能体负责哪一层决策，哪些模块明确留在环境中。</li><li>环境状态包含哪些影响未来演化的变量。</li><li>每个观测量来自哪里，部署时是否可用，频率、噪声和延迟是什么。</li><li>动作表示意图、命令还是实际控制量，中间经过哪些约束与执行环节。</li><li>单步奖励表达什么偏好，累计回报希望塑造什么长期行为。</li><li>哪些安全要求必须作为独立代价、约束或保护机制。</li><li>什么情况属于成功、失败、自然终止与外部截断。</li><li>训练与评估使用哪些指标，是否存在简单可靠的 baseline（基线）。</li></ul><p>如果这些问题无法用普通语言说清楚，暂时不要急着写算法。一个定义清楚的简单环境，比一个概念模糊的高保真仿真更有研究价值。</p><h2 id="十二、接下来进入马尔可夫决策过程" tabindex="-1">十二、接下来进入马尔可夫决策过程 <a class="header-anchor" href="#十二、接下来进入马尔可夫决策过程" aria-label="Permalink to &quot;十二、接下来进入马尔可夫决策过程&quot;">​</a></h2><p>现在已经有了智能体、环境、状态、观测、动作与奖励，还缺少一套能够描述“状态如何转移、策略如何产生长期价值”的数学语言。</p><p>下一篇将进入马尔可夫决策过程，解释马尔可夫性、状态转移概率、奖励函数、策略、回报与折扣因子如何组成统一模型，也会说明自动驾驶任务为什么经常只是近似满足马尔可夫假设。</p><h2 id="十三、结语" tabindex="-1">十三、结语 <a class="header-anchor" href="#十三、结语" aria-label="Permalink to &quot;十三、结语&quot;">​</a></h2><p>强化学习最小闭环看起来只有几根箭头，真正困难的是每根箭头背后的工程语义。</p><p>智能体决定什么，环境模拟什么；状态真实包含什么，观测实际暴露什么；动作希望系统做什么，执行器最终做到了什么；奖励鼓励什么，约束又禁止什么。把这些边界拆清楚，后面的算法和公式才有落脚点。</p><p>模型先于算法。强化学习项目的质量，通常从这六个名词被定义的那一刻就已经开始分化。</p><h2 id="十四、资料来源" tabindex="-1">十四、资料来源 <a class="header-anchor" href="#十四、资料来源" aria-label="Permalink to &quot;十四、资料来源&quot;">​</a></h2><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter1/chapter1.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第 1 章“强化学习基础”原始文档</a></p><p><a href="https://gymnasium.farama.org/api/env/" target="_blank" rel="noreferrer">Gymnasium 环境接口文档</a></p><p><a href="https://gymnasium.farama.org/main/introduction/basic_usage/" target="_blank" rel="noreferrer">Gymnasium 基础使用说明</a></p><p><a href="https://mitpress.mit.edu/9780262039246/reinforcement-learning/" target="_blank" rel="noreferrer">MIT Press（麻省理工学院出版社）《Reinforcement Learning: An Introduction》2nd edition（第 2 版）页面</a></p><p>本项目强化学习基础概念笔记 -- 项目内 <code>docs/rl_basic_concepts.md</code></p><blockquote><p>版权说明：本文基于公开资料与本项目实验经验重新组织，示意图均为本篇原创绘制，不复刻《蘑菇书》原文插图。</p></blockquote>',130)])])}const k=e(h,[["render",p]]);export{f as __pageData,k as default};
